import{z as B,x as s,o as n,c as d,q as A,j as r,D as t,d as e,s as l,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"商品期权与波动率","description":"","frontmatter":{"title":"商品期权与波动率","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-commodity-options.md","filePath":"quant/cn-commodity-options.md","lastUpdated":1791063341000}'),p={name:"quant/cn-commodity-options.md"};function m(u,a,h,D,C,c){const o=s("Mermaid");return n(),d("div",null,[a[2]||(a[2]=A('<h1 id="商品期权与波动率" tabindex="-1">商品期权与波动率 <a class="header-anchor" href="#商品期权与波动率" aria-label="Permalink to &quot;商品期权与波动率&quot;">​</a></h1><div class="epigraph"><p>商品期权长在期货上：标的是期货合约，时段含夜盘，涨跌停与保证金跟商品所走，波动率的季节性来自库存与天气，不是来自 T+1 股票。</p><footer>—— 上海期货交易所、大连商品交易所、郑州商品交易所期权合约与交易规则；对照[到期流程](/quant/options-expiration-process)与商品期货夜盘制度</footer></div><p><a href="/quant/cn-etf-options">上一课</a>停在权益 ETF 期权。本课的缺口是<strong>商品所期权</strong>：以商品期货为标的的期权，在大商所、郑商所、上期所（及能源中心等）上市。夜盘、交割月、持仓限额与期权到期必须联立。不把股票 LOB 的直觉搬来；商品微观结构另有开收盘与停板。后课转债回到交易所股票信用混合产品。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>权益波动率的状态变量是指数与 ETF；商品波动率的状态变量是库存、产季、便利收益与期货曲线形状。期权隐含波动沿期货曲线不同合约而变，近月可以因交割与逼仓预期而显著更高。问题是：商品量化若把「IV–RV」当权益 VRP 同一因子，会忽略季节与期限结构。回测必须按品种–合约月分段，而不是一个「商品期权」池。</p><p><span class="marginnote">术语翻译：「便利收益」就是手里握着现货比握着期货多出来的好处——工厂随时有原料可用、停电时贸易商有货可卖。它使现货紧俏时期货近月比远月更贵（贴水/back 结构），并把波动率沿着曲线重新分配：越靠近交割的合约，隐含波动往往越高。</span></p><p>制度：期权涨跌停、交易保证金、行权（多为美式或欧式以合约为准）、到期与期货交割月的关系，以各所合约表为准。股票 T+1 不适用。夜盘使信息在 A 股收盘后仍写入商品期货与期权，跨资产对冲有时钟差，见<a href="/quant/cn-night-session">夜盘</a>。</p><h3 id="做市、流动性与产业客户" tabindex="-1">做市、流动性与产业客户 <a class="header-anchor" href="#做市、流动性与产业客户" aria-label="Permalink to &quot;做市、流动性与产业客户&quot;">​</a></h3><p>商品期权流动性弱于主力期货，买卖价差宽，产业套保与专业做市占主导。CTA 与期权卖方在保证金上竞争同一现金。容量按期权市场深度与期货对冲可承受冲击估，不按商品现货市场规模估。</p><p><span class="marginnote">黑色、农产品、能化的停板幅度与交易限额不同。2015 年以后各所多次调整，历史必须用当时合约表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主数据按所–品种–合约。波动率曲面挂在对应期货价格上，delta 对冲用该期货，并计入夜盘跳空。季节虚拟变量或库存代理进入 RV 模型，避免把产季高峰当「alpha」。到期：期权到期与期货交割不同步时，基差与转换风险单列。与国债期货期权（若讨论）分开，那是利率市场。</p>',12)),(n(),r(i,null,{default:t(()=>[l(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20POS%5B%22%E6%9C%9F%E6%9D%83%E7%BB%84%E5%90%88%20%E5%93%81%E7%A7%8D-%E5%90%88%E7%BA%A6%E6%9C%88%22%5D%20--%3E%20D%5B%22%E6%8C%89%E6%A0%87%E7%9A%84%E6%9C%9F%E8%B4%A7%E8%AE%A1%E7%AE%97%20delta%22%5D%0A%20%20D%20--%3E%20H%5B%22%E7%94%A8%E8%AF%A5%E6%9C%9F%E8%B4%A7%E5%AF%B9%E5%86%B2%22%5D%0A%20%20NIGHT%5B%22%E5%A4%9C%E7%9B%98%E8%B7%B3%E7%A9%BA%EF%BC%9AA%E8%82%A1%E6%94%B6%E7%9B%98%E5%90%8E%E4%BF%A1%E6%81%AF%E5%86%99%E5%85%A5%22%5D%20--%3E%20H%0A%20%20H%20--%3E%20RB%5B%22%E4%BB%B7%E6%A0%BC%E5%8F%98%E5%8A%A8%E5%90%8E%20delta%20%E6%BC%82%E7%A7%BB%22%5D%0A%20%20RB%20--%3E%7C%22%E5%86%8D%E5%B9%B3%E8%A1%A1%22%7C%20D%0A%20%20H%20--%3E%20M%5B%22%E6%9C%9F%E8%B4%A7%E4%B8%8E%E6%9C%9F%E6%9D%83%E5%90%8C%E4%B8%80%E4%BF%9D%E8%AF%81%E9%87%91%E6%B1%A0%22%5D%0A%20%20M%20--%3E%20CASH%5B%22%E5%8E%8B%E5%8A%9B%E6%97%A5%E5%85%B1%E5%90%8C%E6%8A%BD%E8%B5%B0%E5%8F%AF%E7%94%A8%E7%8E%B0%E9%87%91%22%5D%0A%20%20CASH%20-.%E9%99%90%E5%88%B6%E5%AF%B9%E5%86%B2%E5%8A%A0%E4%BB%93%E8%83%BD%E5%8A%9B.-%20H%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p><span class="marginnote">数字实例：同一账户 100 万元现金，期货腿保证金占 40 万、期权卖方保证金占 30 万。停板扩板或波动放大时两笔保证金同时上调——比如各加 20%——占用从 70 万升到 84 万。若还要在跳空后加仓对冲，现金可能已经不够：「CTA 与期权卖方在保证金上竞争同一现金」说的就是这道闸。</span></p><p>跨市场：用商品期权对冲股票商品链公司，残差含基差、外汇与股票涨跌停。不要假设完美传递。</p><h3 id="波动率风险溢价的样本" tabindex="-1">波动率风险溢价的样本 <a class="header-anchor" href="#波动率风险溢价的样本" aria-label="Permalink to &quot;波动率风险溢价的样本&quot;">​</a></h3><p>中国商品期权上市偏晚，样本短，危机日少。VRP 估计的标准误大。应报告子样本与流动性过滤，而不是一个显著 t 值打天下。这与研究日志课的尝试次数约束一致。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>便利收益使近月期货可以高于远月，期权的远期波动与偏斜随之变。库存信息在现货与仓单上，不一定在股票分析师共识里。因此商品期权隐含对农产品与能化有独立信息，对「全 A 情绪」则噪声更大。保证金联立：期货与期权同一 CCP 池，压力日共同抽 VM。</p>',6)),(n(),r(i,null,{default:t(()=>[l(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Fut%5B%22%E5%95%86%E5%93%81%E6%9C%9F%E8%B4%A7%20%E5%90%AB%E5%A4%9C%E7%9B%98%22%5D%20--%3E%20Opt%5B%22%E5%95%86%E5%93%81%E6%9C%9F%E6%9D%83%22%5D%0A%20%20Inv%5B%22%E5%BA%93%E5%AD%98%E4%B8%8E%E4%BA%A7%E5%AD%A3%22%5D%20--%3E%20RV%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20Opt%20--%3E%20IV%5B%22%E9%9A%90%E5%90%AB%E6%B3%A2%E5%8A%A8%E6%9B%B2%E9%9D%A2%22%5D%0A%20%20IV%20--%3E%20VRP%5B%22IV%20%E5%87%8F%20RV%20%E9%A1%BB%E5%88%86%E6%AE%B5%22%5D%0A%20%20RV%20--%3E%20VRP%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("h2",{id:"边界",tabindex:"-1"},[e("边界 "),E("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=E("p",null,"不提供逼仓、交割月操纵或利用仓单信息违规交易的方法。原油等特定品种有额外监管。场外商品期权与场内不可混用保证金数字。",-1)),a[6]||(a[6]=E("h2",{id:"小结",tabindex:"-1"},[e("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=E("ul",null,[E("li",null,"商品期权的标的是期货，时钟含夜盘，季节性来自库存，不是股票 T+1。"),E("li",null,"VRP 必须按品种与合约月分段；样本短，勿过拟合。"),E("li",null,"容量看期权深度与期货对冲，不看现货市场规模。"),E("li",null,"出处：上期所、大商所、郑商所期权合约与规则。")],-1))])}const V=B(p,[["render",m]]);export{T as __pageData,V as default};
